const b = $('Webhook').first().json.body || {};
const keyword  = (b.keyword  || '').toString().trim();
const location = (b.location || '').toString().trim();
const role     = (b.role     || '').toString().trim();
const country  = ((b.country || 'ID').toString().trim().toUpperCase().slice(0,2)) || 'ID';

// Kode negara -> [nama negara, bahasa hasil]
// Nambah negara? Sisipkan satu baris. Yang gak terdaftar otomatis pakai bahasa Inggris.
const NEGARA={AF:['Afghanistan','fa'],ZA:['South Africa','en'],AL:['Albania','sq'],DZ:['Algeria','ar'],US:['United States','en'],AD:['Andorra','ca'],AO:['Angola','pt'],AG:['Antigua and Barbuda','en'],SA:['Saudi Arabia','ar'],AR:['Argentina','es'],AM:['Armenia','hy'],AU:['Australia','en'],AT:['Austria','de'],AZ:['Azerbaijan','az'],BS:['Bahamas','en'],BH:['Bahrain','ar'],BD:['Bangladesh','bn'],BB:['Barbados','en'],BY:['Belarus','ru'],BE:['Belgium','nl'],BZ:['Belize','en'],BJ:['Benin','fr'],BT:['Bhutan','en'],BO:['Bolivia','es'],BA:['Bosnia and Herzegovina','bs'],BW:['Botswana','en'],BR:['Brazil','pt'],BN:['Brunei','ms'],BG:['Bulgaria','bg'],BF:['Burkina Faso','fr'],BI:['Burundi','fr'],CV:['Cape Verde','pt'],KH:['Cambodia','km'],CM:['Cameroon','fr'],CA:['Canada','en'],CF:['Central African Republic','fr'],TD:['Chad','fr'],CL:['Chile','es'],CN:['China','zh'],CO:['Colombia','es'],KM:['Comoros','ar'],CG:['Republic of the Congo','fr'],CD:['DR Congo','fr'],CR:['Costa Rica','es'],CI:['Ivory Coast','fr'],HR:['Croatia','hr'],CU:['Cuba','es'],CY:['Cyprus','el'],CZ:['Czechia','cs'],DK:['Denmark','da'],DJ:['Djibouti','fr'],DM:['Dominica','en'],DO:['Dominican Republic','es'],EC:['Ecuador','es'],EG:['Egypt','ar'],SV:['El Salvador','es'],GQ:['Equatorial Guinea','es'],ER:['Eritrea','ti'],EE:['Estonia','et'],SZ:['Eswatini','en'],ET:['Ethiopia','am'],FJ:['Fiji','en'],FI:['Finland','fi'],FR:['France','fr'],GA:['Gabon','fr'],GM:['Gambia','en'],GE:['Georgia','ka'],DE:['Germany','de'],GH:['Ghana','en'],GR:['Greece','el'],GD:['Grenada','en'],GT:['Guatemala','es'],GN:['Guinea','fr'],GW:['Guinea-Bissau','pt'],GY:['Guyana','en'],HT:['Haiti','fr'],VA:['Vatican City','it'],HN:['Honduras','es'],HU:['Hungary','hu'],IS:['Iceland','is'],IN:['India','en'],ID:['Indonesia','id'],IR:['Iran','fa'],IQ:['Iraq','ar'],IE:['Ireland','en'],IL:['Israel','iw'],IT:['Italy','it'],JM:['Jamaica','en'],JP:['Japan','ja'],JO:['Jordan','ar'],KZ:['Kazakhstan','kk'],KE:['Kenya','en'],KI:['Kiribati','en'],KP:['North Korea','ko'],KR:['South Korea','ko'],KW:['Kuwait','ar'],KG:['Kyrgyzstan','ky'],LA:['Laos','lo'],LV:['Latvia','lv'],LB:['Lebanon','ar'],LS:['Lesotho','en'],LR:['Liberia','en'],LY:['Libya','ar'],LI:['Liechtenstein','de'],LT:['Lithuania','lt'],LU:['Luxembourg','fr'],MG:['Madagascar','fr'],MW:['Malawi','en'],MY:['Malaysia','ms'],MV:['Maldives','en'],ML:['Mali','fr'],MT:['Malta','en'],MH:['Marshall Islands','en'],MR:['Mauritania','ar'],MU:['Mauritius','en'],MX:['Mexico','es'],FM:['Micronesia','en'],MD:['Moldova','ro'],MC:['Monaco','fr'],MN:['Mongolia','mn'],ME:['Montenegro','sr'],MA:['Morocco','ar'],MZ:['Mozambique','pt'],MM:['Myanmar','my'],NA:['Namibia','en'],NR:['Nauru','en'],NP:['Nepal','ne'],NL:['Netherlands','nl'],NZ:['New Zealand','en'],NI:['Nicaragua','es'],NE:['Niger','fr'],NG:['Nigeria','en'],MK:['North Macedonia','mk'],NO:['Norway','no'],OM:['Oman','ar'],PK:['Pakistan','ur'],PW:['Palau','en'],PS:['Palestine','ar'],PA:['Panama','es'],PG:['Papua New Guinea','en'],PY:['Paraguay','es'],PE:['Peru','es'],PH:['Philippines','en'],PL:['Poland','pl'],PT:['Portugal','pt'],QA:['Qatar','ar'],RO:['Romania','ro'],RU:['Russia','ru'],RW:['Rwanda','en'],KN:['Saint Kitts and Nevis','en'],LC:['Saint Lucia','en'],VC:['Saint Vincent and the Grenadines','en'],WS:['Samoa','en'],SM:['San Marino','it'],ST:['Sao Tome and Principe','pt'],SN:['Senegal','fr'],RS:['Serbia','sr'],SC:['Seychelles','fr'],SL:['Sierra Leone','en'],SG:['Singapore','en'],SK:['Slovakia','sk'],SI:['Slovenia','sl'],SB:['Solomon Islands','en'],SO:['Somalia','so'],ES:['Spain','es'],LK:['Sri Lanka','si'],SD:['Sudan','ar'],SS:['South Sudan','en'],SR:['Suriname','nl'],SE:['Sweden','sv'],CH:['Switzerland','de'],SY:['Syria','ar'],TW:['Taiwan','zh'],TJ:['Tajikistan','tg'],TZ:['Tanzania','sw'],TH:['Thailand','th'],TL:['Timor-Leste','pt'],TG:['Togo','fr'],TO:['Tonga','en'],TT:['Trinidad and Tobago','en'],TN:['Tunisia','ar'],TR:['Turkey','tr'],TM:['Turkmenistan','tk'],TV:['Tuvalu','en'],UG:['Uganda','en'],UA:['Ukraine','uk'],AE:['United Arab Emirates','ar'],GB:['United Kingdom','en'],UY:['Uruguay','es'],UZ:['Uzbekistan','uz'],VU:['Vanuatu','en'],VE:['Venezuela','es'],VN:['Vietnam','vi'],YE:['Yemen','ar'],ZM:['Zambia','en'],ZW:['Zimbabwe','en'],HK:['Hong Kong','zh']};
const info        = NEGARA[country] || [];
const countryName = (b.countryName || info[0] || country).toString().trim();
const language    = (b.language    || info[1] || 'en').toString().trim();

const ALLOWED = ['google_maps','instagram','linkedin'];
let source = String(b.source || 'google_maps').toLowerCase();
if (ALLOWED.indexOf(source) < 0) source = 'google_maps';

let desired = parseInt(b.limit, 10);
if (!desired || desired < 1) desired = 25;
desired = Math.min(50, desired);

// Selalu sertakan nama negara — tanpa itu "Sydney" atau "Cambridge" bisa nyasar
const tempat  = location ? (location + ', ' + countryName) : countryName;
const igQuery = (keyword + (location ? (' ' + location) : '')).trim();
const liQuery = (((role ? role + ' ' : '') + keyword).trim()) || keyword;
const liBody  = { searchQuery: liQuery, maxItems: desired, profileScraperMode: 'Full + email search', locations: [tempat] };
if (role) liBody.currentJobTitles = [role];

return [{ json: {
  hasKeyword: keyword.length > 0,
  keyword, location, role, country, countryName, language, desired, source,
  googleSheetId: $('⚙️ Config').first().json.googleSheetId,
  jobId:       b.jobId       || '',
  callbackUrl: b.callbackUrl || '',
  mapsBody: { searchStringsArray: [keyword], locationQuery: tempat, maxCrawledPlacesPerSearch: desired, language: language, skipClosedPlaces: false, scrapeContacts: true },
  igBody: { search: (igQuery || keyword), searchType: 'user', searchLimit: desired, enhanceUserSearchWithFacebookPage: false },
  liBody
} }];

const esc=s=>String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const arr=v=>Array.isArray(v)?v.filter(x=>x!==undefined&&x!==null&&x!==''):(v?[v]:[]);
const apifyRows=$('Apify - Google Maps').all(); let places=[];
for(const r of apifyRows){const j=r.json; if(Array.isArray(j))places.push(...j); else if(j&&Array.isArray(j.data))places.push(...j.data); else places.push(j);}
const pp=$('Parse Params').first().json; const kw=pp.keyword||''; const loc=pp.location||''; const kwE=esc(kw); const locE=esc(loc);
const sheetUrl='https://docs.google.com/spreadsheets/d/'+($('⚙️ Config').first().json.googleSheetId)+'/edit';
const errP=places.find(a=>a&&a.error&&!a.placeId&&!a.title);
if(errP){ return [{ json:{ count:0, keyword:kw, summaryText:`⚠️ Google Maps scraper error: ${esc(errP.error)}. Coba lagi atau ubah keyword.`, sheetUrl, leads:[] } }]; }
const existRows=$input.all().map(r=>r.json||{});
const existPid=new Set(); for(const e of existRows){ if(e.place_id!==undefined&&e.place_id!=='') existPid.add(String(e.place_id)); }
const pickSocial=(p,keys)=>{ for(const k of keys){ const a=arr(p[k]); if(a.length) return a[0]; } return ''; };
const leads=[]; let withPhone=0; let withEmail=0; let skippedDup=0; const seen=new Set();
for(const p of places){ if(!p||typeof p!=='object'||!(p.title||p.placeId))continue;
 const pid=String(p.placeId||'');
 if(pid && existPid.has(pid)){ skippedDup++; continue; }
 if(pid && seen.has(pid)) continue; if(pid) seen.add(pid);
 const phone=p.phone||p.phoneUnformatted||''; if(phone)withPhone++;
 const email=(arr(p.emails).concat(arr(p.email)))[0]||''; if(email)withEmail++;
 const instagram=pickSocial(p,['instagrams','instagram','instagramUrl','instagramUrls']);
 leads.push({ scraped_at:new Date().toISOString(), keyword:kw, location:loc, name:p.title||'', category:p.categoryName||(Array.isArray(p.categories)?p.categories.join(', '):'')||'', address:p.address||'', city:p.city||'', phone:p.phone||'', phone_unformatted:p.phoneUnformatted||'', website:p.website||'', email:email, ig:instagram, rating:(p.totalScore!==undefined?p.totalScore:''), reviews:(p.reviewsCount!==undefined?p.reviewsCount:''), maps_url:p.url||'', place_id:pid, source:'gmaps' });
}
const total=places.length;
const dupNote=skippedDup>0?` (${skippedDup} udah ada di sheet, dilewati)`:'';
let summary;
if(leads.length===0){ summary=`🔍 Selesai cari "${kwE}"${loc?(' di '+locE):''} di Google Maps. Nggak ada bisnis BARU${dupNote}. Coba keyword/lokasi lain.`; }
else { summary=`✅ ${leads.length} bisnis BARU dari Google Maps untuk "${kwE}"${loc?(' di '+locE):''} (${withPhone} ada telp, ${withEmail} ada email)${dupNote}.\n\n📄 Tersimpan di tab "Maps Leads":\n${sheetUrl}`; }
return [{ json:{ count:leads.length, total, keyword:kw, summaryText:summary, sheetUrl, leads } }];

const esc=s=>String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const rows=$('Apify - Instagram').all(); let items=[];
for(const r of rows){const j=r.json; if(Array.isArray(j))items.push(...j); else if(j&&Array.isArray(j.data))items.push(...j.data); else if(j&&Array.isArray(j.users))items.push(...j.users); else items.push(j);}
const pp=$('Parse Params').first().json; const kw=pp.keyword||''; const loc=pp.location||''; const kwE=esc(kw); const locE=esc(loc);
const sheetUrl='https://docs.google.com/spreadsheets/d/'+($('⚙️ Config').first().json.googleSheetId)+'/edit';
const existRows=$input.all().map(r=>r.json||{});
const existU=new Set(); for(const e of existRows){ if(e.username!==undefined&&e.username!=='') existU.add(String(e.username).toLowerCase()); }
const pick=(o,keys)=>{ for(const k of keys){ if(o[k]!==undefined&&o[k]!==null&&o[k]!=='') return o[k]; } return ''; };
const leads=[]; let skippedDup=0; const seen=new Set();
for(const u of items){ if(!u||typeof u!=='object')continue;
 const username=String(pick(u,['username','userName','user_name'])||'').trim();
 if(!username)continue;
 const ul=username.toLowerCase();
 if(existU.has(ul)){ skippedDup++; continue; }
 if(seen.has(ul))continue; seen.add(ul);
 const full_name=pick(u,['fullName','full_name','fullname','name']);
 const followers=pick(u,['followersCount','followers','follower_count','followers_count']);
 const posts_count=pick(u,['postsCount','posts_count','mediaCount','media_count']);
 let category=String(pick(u,['businessCategoryName','categoryName','category','category_name'])||'').replace(/^None,?/i,'').trim(); if(category.toLowerCase()==='none')category='';
 const bio=pick(u,['biography','bio','description']);
 let phone=String(pick(u,['phone','public_phone_number','contactPhoneNumber','phoneNumber'])||'');
 let website='';
 const exts=Array.isArray(u.externalUrls)?u.externalUrls:[];
 for(const ex of exts){ const url=String((ex&&ex.url)||''); const lt=String((ex&&ex.link_type)||'');
  if((lt==='whatsapp'||/wa\.me|whatsapp/i.test(url))){ if(!phone){ const m=url.match(/wa\.me\/(\d+)/)||url.match(/phone(?:Number)?=(\d+)/); if(m)phone=m[1]; } }
  else if(!website && url){ website=url; } }
 if(!website){ const eu=String(pick(u,['externalUrl','website','external_url'])||''); if(eu&&!/wa\.me|whatsapp/i.test(eu))website=eu; }
 const email=pick(u,['email','public_email','businessEmail','business_email','publicEmail']);
 const is_verified=(u.verified===true||u.is_verified===true||u.isVerified===true);
 const profile_url=String(pick(u,['url','inputUrl','profile_url','profileUrl'])||('https://www.instagram.com/'+username+'/'));
 leads.push({ scraped_at:new Date().toISOString(), keyword:kw, username, full_name:full_name||'', followers:(followers===''?'':followers), posts_count:(posts_count===''?'':posts_count), category:category||'', bio:bio||'', website:website||'', email:email||'', phone:phone||'', is_verified, profile_url, source:'instagram' });
}
const total=items.length;
const withWa=leads.filter(l=>l.phone).length;
const withContact=leads.filter(l=>l.phone||l.email||l.website).length;
const dupNote=skippedDup>0?` (${skippedDup} udah ada di sheet, dilewati)`:'';
const errItem=items.find(a=>a&&a.error&&!a.username);
let summary;
if(leads.length===0){ if(errItem){ summary=`⚠️ Instagram: ${esc(errItem.error)}. Coba keyword lain atau lebih spesifik.`; } else { summary=`🔍 Selesai cari "${kwE}"${loc?(' di '+locE):''} di Instagram. Nggak ada profil BARU${dupNote}. Coba keyword lain.`; } }
else { summary=`✅ ${leads.length} profil IG BARU untuk "${kwE}"${loc?(' di '+locE):''} (${withWa} ada nomor WA, ${withContact} ada kontak/website)${dupNote}.\n\n📄 Tersimpan di tab "IG Leads":\n${sheetUrl}`; }
return [{ json:{ count:leads.length, total, keyword:kw, summaryText:summary, sheetUrl, leads } }];

const esc=s=>String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const rows=$('Apify - LinkedIn').all(); let items=[];
for(const r of rows){const j=r.json; if(Array.isArray(j))items.push(...j); else if(j&&Array.isArray(j.data))items.push(...j.data); else if(j&&Array.isArray(j.elements))items.push(...j.elements); else items.push(j);}
const pp=$('Parse Params').first().json; const kw=pp.keyword||''; const loc=pp.location||''; const kwE=esc(kw); const locE=esc(loc);
const sheetUrl='https://docs.google.com/spreadsheets/d/'+($('⚙️ Config').first().json.googleSheetId)+'/edit';
const existRows=$input.all().map(r=>r.json||{});
const existKey=new Set();
for(const e of existRows){ const k=String(e.public_id||e.linkedin_url||'').toLowerCase(); if(k)existKey.add(k); }
const pick=(o,keys)=>{ for(const k of keys){ if(o&&o[k]!==undefined&&o[k]!==null&&o[k]!=='') return o[k]; } return ''; };
const firstOf=(v)=>Array.isArray(v)?(v[0]||''):v;
const leads=[]; let skippedDup=0; const seen=new Set();
for(const u of items){ if(!u||typeof u!=='object')continue;
 if(u.error&&!u.id&&!u.publicIdentifier&&!u.linkedinUrl&&!u.url)continue;
 const linkedin_url=String(pick(u,['linkedinUrl','url','profileUrl','publicUrl'])||'');
 let public_id=String(pick(u,['publicIdentifier','publicId','username'])||'');
 if(!public_id&&linkedin_url){ const m=linkedin_url.match(/\/in\/([^/?#]+)/); if(m)public_id=m[1]; }
 const key=(public_id||linkedin_url).toLowerCase();
 if(!key)continue;
 if(existKey.has(key)){skippedDup++;continue;}
 if(seen.has(key))continue; seen.add(key);
 const firstName=pick(u,['firstName','first_name']);
 const lastName=pick(u,['lastName','last_name']);
 let name=pick(u,['name','fullName','full_name']); if(!name)name=((firstName?firstName:'')+' '+(lastName?lastName:'')).trim();
 const headline=pick(u,['headline','occupation','subtitle']);
 let cp=u.currentPosition||u.currentJob||(Array.isArray(u.experience)?u.experience[0]:null)||(Array.isArray(u.positions)?u.positions[0]:null)||(Array.isArray(u.experiences)?u.experiences[0]:null);
 if(Array.isArray(cp))cp=cp[0];
 let job_title=cp?pick(cp,['title','position','jobTitle','role']):''; if(!job_title)job_title=pick(u,['jobTitle','title']);
 let company=cp?pick(cp,['companyName','company','company_name','organization']):''; if(company&&typeof company==='object')company=pick(company,['name','companyName']); if(!company)company=pick(u,['companyName','company']); if(company&&typeof company==='object')company=pick(company,['name','companyName']);
 let location=u.location; if(location&&typeof location==='object')location=pick(location,['linkedinText','parsed','text','name','default']); location=String(location||pick(u,['locationName','geoLocation'])||'');
 let email=pick(u,['email','workEmail','businessEmail']); if(!email)email=firstOf(u.emails)||''; if(email&&typeof email==='object')email=pick(email,['email','value','address']);
 let phone=pick(u,['phone','phoneNumber']); if(!phone)phone=firstOf(u.phones)||firstOf(u.phoneNumbers)||''; if(phone&&typeof phone==='object')phone=pick(phone,['phone','number','value']);
 leads.push({ scraped_at:new Date().toISOString(), keyword:kw, name:name||'', first_name:firstName||'', last_name:lastName||'', headline:headline||'', job_title:job_title||'', company:company||'', location:location||'', email:email||'', phone:phone||'', linkedin_url:linkedin_url||(public_id?('https://www.linkedin.com/in/'+public_id):''), public_id:public_id||'', source:'linkedin' });
}
const total=items.length;
const withEmail=leads.filter(l=>l.email).length;
const dupNote=skippedDup>0?` (${skippedDup} udah ada di sheet, dilewati)`:'';
const errItem=items.find(a=>a&&a.error&&!a.publicIdentifier&&!a.linkedinUrl&&!a.url);
let summary;
if(leads.length===0){ if(errItem){summary=`⚠️ LinkedIn: ${esc(errItem.error)}. Coba keyword lain.`;} else {summary=`🔍 Selesai cari "${kwE}"${loc?(' di '+locE):''} di LinkedIn. Nggak ada profil BARU${dupNote}. Coba keyword/role lain.`;} }
else { summary=`✅ ${leads.length} profil LinkedIn BARU untuk "${kwE}"${loc?(' di '+locE):''} (${withEmail} ada email)${dupNote}.\n\n📄 Tersimpan di tab "LinkedIn Leads":\n${sheetUrl}`; }
return [{ json:{ count:leads.length, total, keyword:kw, summaryText:summary, sheetUrl, leads } }];
